DO $fix$ DECLARE s text;BEGIN
s:=pg_get_functiondef('public.record_issue_notification()'::regprocedure);s:=replace(s,$old$IF NEW.visibility='internal' AND NEW.kind<>'supervisor_instruction' THEN RETURN NEW; END IF;$old$,$new$IF NEW.visibility='internal' AND NEW.kind NOT IN ('supervisor_instruction','integrity_response') THEN RETURN NEW; END IF;$new$);s:=replace(s,$old$typ:=CASE WHEN NEW.kind='created'$old$,$new$typ:=CASE WHEN NEW.kind LIKE 'integrity_%' THEN 'report_review' WHEN NEW.kind='created'$new$);EXECUTE s;
s:=pg_get_functiondef('public.purge_demo_dataset(text)'::regprocedure);s:=replace(s,'DELETE FROM public.issue_feedback', 'DELETE FROM public.report_integrity_audit a USING public.issues i WHERE a.issue_id=i.id AND i.demo_dataset_id=_dataset; DELETE FROM public.report_integrity r USING public.issues i WHERE r.issue_id=i.id AND i.demo_dataset_id=_dataset; DELETE FROM public.issue_feedback');EXECUTE s;
END $fix$;
CREATE OR REPLACE FUNCTION public.list_expired_report_uploads() RETURNS TABLE(key uuid,original_path text) LANGUAGE sql SECURITY DEFINER SET search_path=public AS $$ SELECT r.key,r.original_path FROM public.report_upload_reservations r WHERE r.expires_at<now() AND NOT r.consumed AND NOT EXISTS(SELECT 1 FROM public.issue_photos p WHERE p.original_path=r.original_path) ORDER BY r.expires_at LIMIT 100 $$;
REVOKE ALL ON FUNCTION public.list_expired_report_uploads() FROM PUBLIC,anon,authenticated;GRANT EXECUTE ON FUNCTION public.list_expired_report_uploads() TO service_role;
CREATE OR REPLACE FUNCTION public.complete_expired_report_upload(_key uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN DELETE FROM public.report_upload_reservations WHERE key=_key AND expires_at<now() AND NOT consumed;END $$;
REVOKE ALL ON FUNCTION public.complete_expired_report_upload(uuid) FROM PUBLIC,anon,authenticated;GRANT EXECUTE ON FUNCTION public.complete_expired_report_upload(uuid) TO service_role;